LETTERS.update({'ё':'yo','й':'j','ы':'y','ь':'soft','ъ':'hard'})

def rat(value):
    s=str(value).replace(',','.').strip()
    if ' ' in s:
        whole, rest=s.split()
        return F(whole) + (-1 if whole.startswith('-') else 1)*F(rest)
    return F(s)

def fs(value):
    v=rat(value)
    return str(v.numerator) if v.denominator==1 else f'{v.numerator}/{v.denominator}'

def pretty(value):
    v=rat(value)
    d=v.denominator
    for p in (2,5):
        while d%p==0:d//=p
    if d==1:
        from decimal import Decimal, localcontext
        with localcontext() as c:
            c.prec=60
            out=format(Decimal(v.numerator)/Decimal(v.denominator),'f')
        if '.' in out:out=out.rstrip('0').rstrip('.')
        return out.replace('.',',')
    return fs(v)

def expr(src):
    def walk(n):
        if isinstance(n,ast.Constant) and isinstance(n.value,(str,int,float)):
            # Source text is used for decimals to avoid binary float conversion.
            return n.value if isinstance(n.value,str) else ast.get_source_segment(src,n)
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='m' and len(n.args)==3:
            w,a,b=[int(x.value) for x in n.args]
            return f'{w} {a}/{b}'
        if isinstance(n,ast.BinOp):
            ops={ast.Add:'add',ast.Sub:'subtract',ast.Mult:'multiply',ast.Div:'divide'}
            if type(n.op) in ops:return {'op':ops[type(n.op)],'left':walk(n.left),'right':walk(n.right)}
        raise ValueError(f'Unsupported expression: {src}')
    return walk(ast.parse(src,mode='eval').body)

def ev(node):
    if isinstance(node,str):return rat(node)
    a,b=ev(node['left']),ev(node['right'])
    return {'add':lambda:a+b,'subtract':lambda:a-b,'multiply':lambda:a*b,'divide':lambda:a/b}[node['op']]()

def exact_steps(node):
    steps=[]
    def visit(n):
        if isinstance(n,str):return rat(n)
        a,b=visit(n['left']),visit(n['right']);v=ev(n)
        sign={'add':'+','subtract':'−','multiply':'·','divide':':'}[n['op']]
        steps.append({'prompt':f'Вычисли {pretty(a)} {sign} {pretty(b)}.','answer':fs(v),'explanation':f'{pretty(a)} {sign} {pretty(b)} = {pretty(v)}.','hint':{'add':'Приведи числа к удобной общей записи и сложи.','subtract':'Приведи числа к удобной общей записи и вычти.','multiply':'Для дробей можно предварительно сократить множители.','divide':'Деление на дробь замени умножением на обратную; деление на десятичную дробь — делением на целое после переноса запятой в обоих числах.'}[n['op']]})
        return v
    visit(node)
    return steps

def rounded(v, places):
    scale=F(10)**places
    x=v*scale
    sign=-1 if x<0 else 1
    x=abs(x)
    return F(sign*((2*x.numerator+x.denominator)//(2*x.denominator)),1)/scale

def W(label,prompt,answer,explanation=None,criteria=None,steps=None):
    explanation=explanation or answer
    return {'label':label,'kind':'written','prompt':prompt,'answer':answer,'explanation':explanation,
            'criteria':criteria or [answer],
            'steps':steps or [{'prompt':'Какие свойства или правило нужны для этого пункта?','explanation':explanation,'hint':'Сопоставь утверждение с его точным смыслом; для опровержения достаточно одного контрпримера.'},{'prompt':'Запиши ответ и обоснуй его.','answer':answer,'explanation':explanation}]}

def N(label,prompt,answer,steps,explanation=None):
    if not steps or 'answer' not in steps[-1] or rat(steps[-1]['answer']) != rat(answer):
        steps=steps+[S('Запиши итоговый ответ на вопрос этого пункта.',answer,f'Ответ: {pretty(answer)}.')]
    return {'label':label,'kind':'numeric','prompt':prompt,'answer':fs(answer),'steps':steps,'explanation':explanation or f'Ответ: {pretty(answer)}.'}

def S(prompt,answer,explanation,hint=None):
    q={'prompt':prompt,'answer':fs(answer),'explanation':explanation}
    if hint:q['hint']=hint
    return q

def E(label,src,prompt=None,places=None):
    node=expr(src); val=ev(node)
    p={'label':label,'kind':'expression','prompt':prompt or src,'expression':node,'answer':fs(val),'steps':exact_steps(node),'explanation':f'Точное значение: {pretty(val)}.'}
    if places is not None:
        p['rounding']={'places':places};p['answer']=fs(rounded(val,places))
        precision={-2:'сотен',-1:'десятков',0:'целых',1:'десятых',2:'сотых',3:'тысячных',4:'десятитысячных'}[places]
        p['steps'].append(S(f'Округли результат до {precision}.',p['answer'],f'Точное значение {pretty(val)}; после округления {pretty(p["answer"])}.','Посмотри на следующую цифру: 0–4 — сохраняем разряд, 5–9 — увеличиваем его на 1.'))
        p['explanation']+=f' После округления: {pretty(p["answer"])}.'
    return p

def C(label,prompt,choices,answer,explanation):
    assert answer in choices
    return {'label':label,'kind':'choice','prompt':prompt,'choices':choices,'answer':answer,'steps':[{'prompt':'Какое правило помогает выбрать верный вариант?','explanation':explanation},{'prompt':'Выбери ответ.','answer':answer,'explanation':explanation}],'explanation':explanation}

def add(number,prompt,parts,page=None):
    for i,p in enumerate(parts,1):
        label=p['label']
        slug=''.join(LETTERS.get(c,c) if c.isalnum() else '-' for c in label.lower()).strip('-') or str(i)
        while '--' in slug:slug=slug.replace('--','-')
        p['id']=f'{number:03}-{slug}'
        p['sourcePage']=page or PAGES[number]
    assert len({p['id'] for p in parts})==len(parts),(number,'duplicate labels')
    BOOK.append({'number':number,'prompt':prompt,'sourcePage':page or PAGES[number],'parts':parts,'coverage':{'sourceVerified':True,'subpartsComplete':True}})

def negs(number,prompt,rows):
    parts=[]
    for i,(statement,negative,*why) in enumerate(rows,1):
        explanation=(why[0] if why else 'Исходное утверждение и его отрицание не могут быть одновременно истинными или одновременно ложными.')
        parts.append(W(f'{i})',statement,negative,explanation,
            [f'Получено отрицание: «{negative}».','Сохранены предметы и условия исходного утверждения.','Объяснено, почему высказывание и его отрицание имеют противоположные значения истинности.'],
            [{'prompt':'Поставь перед всем утверждением слова «Неверно, что».','answer':'Неверно, что '+statement[0].lower()+statement[1:],'explanation':'Отрицать нужно всё высказывание, а не отдельное слово.'},{'prompt':'Перефразируй отрицание без изменения смысла.','answer':negative,'explanation':explanation}]))
    add(number,prompt,parts)

