add(16,'Назови способы сравнения обыкновенных дробей и сравни пары.',[C(l+')',f'{a} и {b}',['<','=','>'],sg,w) for l,a,b,sg,w in [('а','9/25','8/25','>','Знаменатели равны: 9 > 8.'),('б','5/19','5/12','<','Числители равны; 19 > 12.'),('в','111/53','79/84','>','111/53 > 1, а 79/84 < 1.'),('г','4/7','3/5','<','4/7 = 20/35, 3/5 = 21/35.'),('д','44/45','45/46','<','До единицы не хватает 1/45 и 1/46; 1/45 больше, значит 44/45 меньше.')]])
add(17,'Реши задачи.',[
N('а)','В первом отряде 25 человек, во втором в 1,2 раза больше, в третьем на 7 меньше, чем во втором. Всех разделили на две равные команды. Сколько человек в каждой?','39',[S('Сколько человек во втором отряде?','30','25·1,2=30.'),S('Сколько в третьем?','23','30−7=23.'),S('Сколько во всех отрядах?','78','25+30+23=78.'),S('Сколько в каждой из двух команд?','39','78:2=39.')]),
N('б)','За 28 дней надо израсходовать 1 т картофеля. Первые 12 дней расходовали по 38 кг. Сколько кг в день можно расходовать в оставшиеся дни поровну?','34',[S('Сколько кг израсходовали за первые 12 дней?','456','38·12=456 кг.'),S('Сколько кг осталось?','544','1000−456=544 кг.'),S('Сколько дней осталось?','16','28−12=16 дней.'),S('Найди ежедневный расход.','34','544:16=34 кг.')])])
add(18,'Нарисуй диаграмму множеств: M — все планеты, названия которых начинаются с М; C — все планеты Солнечной системы; Г — её планеты-гиганты. Отметь Землю.',[W('1','Покажи отношения множеств и положение Земли.','В школьной модели рассматриваемых планет M={Меркурий;Марс}⊂C; Г⊂C; M∩Г=∅. Земля лежит в C вне M и Г.','Гиганты: Юпитер, Сатурн, Уран, Нептун. Для привычного набора планет рисуем внутри C два непересекающихся множества M и Г. Если выражение «все планеты» распространять также на внесолнечные, область M нужно уточнить; положение Земли, Меркурия, Марса и гигантов остаётся тем же.', ['В принятой учебной области M и Г находятся внутри C и не пересекаются.','В M находятся Меркурий и Марс, в Г — четыре планеты-гиганта.','Земля отмечена внутри C, вне M и Г.'])])
add(19,'Найди ложные высказывания и построй их отрицания; при необходимости сверь факт со справочником.',[
W('1)','Джордано Бруно был последователем учения Птолемея.','Ложно. Бруно не был последователем учения Птолемея.','Бруно поддерживал гелиоцентрические идеи Коперника.'),
W('2)','Пальмы — самые высокие деревья в мире.','Ложно. Пальмы не являются самыми высокими деревьями в мире.','Высочайшие деревья относятся к секвойям.'),
W('3)','В атмосфере Земли кислорода по массе не меньше, чем азота.','Ложно. Кислорода по массе меньше, чем азота.','В сухом воздухе массовая доля азота около 75,5%, кислорода около 23,1%.'),
W('4)','Площадь Германии больше площади Франции.','Ложно. Площадь Германии не больше площади Франции.','Площадь Франции больше даже при сравнении только её европейской территории.'),
W('5)','Санкт-Петербург был основан в 1704 или 1705 году.','Ложно. Санкт-Петербург не был основан ни в 1704, ни в 1705 году.','Город основан в 1703 году.'),
W('6)','Кенгуру живут не то в Австралии, не то в Антарктиде.','При логическом понимании «или» — истинно: кенгуру живут в Австралии. В список ложных этот пункт не включаем.','Оборот «не то … не то …» выражает разговорную неопределённость. При формальном понимании альтернатив исходное высказывание истинно; его отрицание «Кенгуру не живут ни в Австралии, ни в Антарктиде» ложно.', ['Разъяснён смысл оборота «не то … не то …».','Не объявлено ложным истинное логическое «или».','При построении отрицания исключены оба варианта.'])])
add(20,'Запиши предложение на математическом языке и построй отрицание.',[W(str(i)+')',p,a,w) for i,(p,a,w) in enumerate([
('Число x меньше пяти девятых.','x < 5/9; отрицание: x ≥ 5/9.','Отрицание строгого «меньше» — «больше или равно».'),('Число y больше или равно трём целым четырём тысячным.','y ≥ 3,004; отрицание: y < 3,004.','Четыре тысячных — 0,004.'),('Разность чисел a и b равна c.','a−b=c; отрицание: a−b≠c.','Отрицание равенства — неравенство.'),('Квадрат числа n не равен 16.','n²≠16; отрицание: n²=16.','Двойное отрицание возвращает равенство.'),('Число x больше своего квадрата.','x>x²; отрицание: x≤x².','Отрицаем знак >.'),('Число x меньше своего квадрата на 1.','x=x²−1; отрицание: x≠x²−1.','Оборот «на 1» задаёт равенство разности единице, а не просто сравнение.')],1)])
add(21,'Построй отрицание высказывания «Все реки впадают в Каспийское море» и проверь закон исключённого третьего.',[W('1','Построй отрицание и приведи контрпример.','Существует хотя бы одна река, которая не впадает в Каспийское море.','Например, Нева впадает в Финский залив. Исходное утверждение ложно, отрицание истинно.')])
