def factors(n):
    parts=[];d=2
    while d*d<=n:
        while n%d==0:parts.append(str(d));n//=d
        d+=1
    if n>1:parts.append(str(n))
    return '·'.join(parts) or '1'

def gcdlcm(label,values,prompt=None):
    g=math.gcd(*values);l=math.lcm(*values)
    text=prompt or ' и '.join(map(str,values))
    why='; '.join(f'{n}={factors(n)}' for n in values)+'. Для НОД берём общие простые множители с наименьшими показателями, для НОК — все с наибольшими.'
    return W(label,text,f'НОД={g}; НОК={l}.',why,[f'НОД равен {g}.',f'НОК равен {l}.','Обоснование использует разложения на простые множители.'],[{'prompt':'Разложи каждое число на простые множители.','explanation':why},S('Найди НОД.',g,f'Общие простые множители дают {g}.'),S('Найди НОК.',l,f'Множители в наибольших степенях дают {l}.')])
