add(55,'Измерь длину и ширину своей комнаты в метрах до десятых. Найди периметр и площадь; округли до целых.',[W('1','Используй собственные измерения.','Для измеренных a и b: P=2(a+b) м, S=ab м²; округли каждый результат до целых.','Единственного числового ответа нет. Например, при a=4,2 и b=3,6: P=15,6≈16 м; S=15,12≈15 м².', ['Записаны собственные длина и ширина с точностью до десятых метра.','Периметр вычислен как 2(a+b), площадь как ab.','Ответы округлены только после вычисления.','Единицы: м и м².'],[{'prompt':'Измерь и запиши a и b.','explanation':'Каждое измерение запиши до десятых метра.'},{'prompt':'Вычисли периметр и площадь по своим данным.','explanation':'P=2(a+b); S=ab.'},{'prompt':'Округли оба результата до целых и подпиши единицы.','explanation':'Смотри на цифру десятых; площадь измеряется в м².'}])])
