add(57,'Алик и Боря вместе собрали столько же грибов, сколько Витя и Гена. Алик и Гена вместе — меньше, чем Боря и Витя. Гена собрал больше Вити. Расположи имена по убыванию числа грибов.',[W('1','Докажи порядок.','Боря, Гена, Витя, Алик.','Пусть количества A,Б,В,Г. Из A+Б=В+Г получаем A=В+Г−Б. Подставив в A+Г<Б+В, получаем Г<Б. Тогда A=В−(Б−Г)<В. Вместе с Г>В: Б>Г>В>A.', ['Использованы оба равенство/неравенство, а не только Г>В.','Доказаны Б>Г и В>A.','Получен порядок Б>Г>В>A.'],[{'prompt':'Вырази количество Алика из равенства сумм.','answer':'A=В+Г−Б','explanation':'A+Б=В+Г.'},{'prompt':'Подставь его во второе условие и сравни Борю с Геной.','answer':'Б>Г','explanation':'В+2Г−Б<Б+В, значит 2Г<2Б.'},{'prompt':'Теперь сравни Алика с Витей.','answer':'A<В','explanation':'A=В−(Б−Г), а Б−Г>0.'},{'prompt':'Объедини сравнения.','answer':'Боря > Гена > Витя > Алик','explanation':'Используем также данное Г>В.'}])])
add(58,'Расшифруй по таблице запись: 61551491 * 2 * 6561 * 051 * 51516566.',[W('1','Используй соответствия букв и цифр исходной таблицы.','ТЕРПЕНЬЕ И ТРУД ВСЕ ПЕРЕТРУТ.','61551491 → терпенье; 2 → и; 6561 → труд; 051 → все; 51516566 → перетрут. Звёздочки здесь обозначают пробелы.', ['Каждая буква относится к столбцу соответствующей цифры.','Сохранены длины слов 8–1–4–3–8.','Получена связная пословица.'])])

