def graph(label,prompt,answer,formula,table,description,domain):
    return W(label,prompt,answer,description,[f'Формула: {formula}.',f'Допустимые значения: {domain}.',f'Таблица или контрольные точки: {table}.','Оси подписаны и масштаб выбран равномерно.','График соответствует формуле на всём указанном промежутке.'],[{'prompt':'Запиши зависимость и допустимые значения.','answer':formula+'; '+domain,'explanation':description},{'prompt':'Заполни таблицу значений.','answer':table,'explanation':'Подставляй каждое значение независимой переменной в формулу.'},{'prompt':'Построй график по таблице; подпиши оси и единицы.','explanation':description}])
