pairs110=[('а','x+2y=9',[(x,y) for x in range(1,10) for y in range(1,10) if x+2*y==9],'y может быть только 1,2,3,4; x=9−2y.'),('б','x+y²=9',[(x,y) for x in range(1,10) for y in range(1,4) if x+y*y==9],'y=1 или 2; при y≥3 положительного x не получится.'),('в','0<x(10−3y)≤2',[(x,y) for x in range(1,3) for y in range(1,4) if 0<x*(10-3*y)<=2],'Положительный множитель 10−3y равен 7,4 или 1. Подходит только y=3.'),('г','0<x(10−y³)≤2',[(x,y) for x in range(1,3) for y in range(1,3) if 0<x*(10-y**3)<=2],'При y=1 множитель 9 слишком велик; при y=2 множитель 2, значит x=1.'),('д','15<2x+3y≤16',[(x,y) for x in range(1,9) for y in range(1,6) if 15<2*x+3*y<=16],'Целая сумма равна 16; перебери положительные y≤5.'),('е','15<x²+y³≤16',[(x,y) for x in range(1,5) for y in range(1,3) if 15<x*x+y**3<=16],'Нужно x²+y³=16. При y=1 квадрат должен равняться 15, при y=2 — 8; оба невозможны.')]
add(110,'Упорядоченные пары: прочитай определение и выполни перебор.',[W('1)','Как называется пара с отмеченным первым и вторым числом?','Упорядоченная пара (a;b); (a;b)=(c;d) тогда и только тогда, когда a=c и b=d.','Порядок важен: обычно (a;b)≠(b;a).')]+[W('2-'+l,p,('; '.join(f'({x};{y})' for x,y in pairs)+'.') if pairs else 'Решений нет: ∅.',why) for l,p,pairs,why in pairs110])
