add(119,'При делении натурального числа на 8 остаток 5. Каков остаток при делении удвоенного числа на 8?',[N('1','Пусть число 8k+5.','2',[S('Удвой остаточную часть 5.','10','2(8k+5)=16k+10.'),S('Найди остаток 10 при делении на 8.','2','10=8+2; 2n=8(2k+1)+2.')])])
rows120=[('∀a∈A: a имеет дневник; A — ученики.','У каждого ученика есть дневник; все ученики имеют дневники.'),('∃b∈A: b пишет стихи; A — ученики.','Есть хотя бы один ученик, который пишет стихи; некоторые ученики пишут стихи.'),('∃x∈B: x имеет синоним; B — русские слова.','В русском языке есть слово, имеющее синоним.'),('∀y∈B: y является глаголом; B — русские слова.','Каждое слово русского языка является глаголом.'),('∃m,n∈P: m∥n; P — прямые плоскости.','На плоскости существуют параллельные прямые.'),('∀A,B∈C: AO=OB; C — точки окружности с центром O.','Любые две точки окружности равноудалены от её центра; все радиусы этой окружности равны.'),('∀a,b∈N: a>b, или a<b, или a=b.','Для любых двух натуральных чисел первое больше второго, меньше второго или равно ему.'),('∃x,y,z∈N: x+y+z=xyz.','Существуют три натуральных числа, сумма которых равна их произведению.')]
add(120,'Переведи высказывания на русский язык разными способами.',[W(f'{i})',p,a,'Квантор ∀ читается «для каждого», ∃ — «существует хотя бы один». Множество переменных сохраняется.') for i,(p,a) in enumerate(rows120,1)])
rows121=[('У каждой реки есть исток.','Пусть R — реки. ∀r∈R: у r есть исток.'),('Есть реки длиннее Нила.','Пусть R — реки, L(r) — длина. ∃r∈R: L(r)>L(Нил).'),('Все дельфины живут в воде.','Пусть D — дельфины. ∀d∈D: d живёт в воде.'),('Некоторые дети умеют кататься на велосипеде.','Пусть C — дети. ∃c∈C: c умеет кататься на велосипеде.'),('Диаметры одной окружности равны.','Пусть D — диаметры одной фиксированной окружности. ∀d₁,d₂∈D: длина(d₁)=длина(d₂).'),('Прямые при пересечении могут образовывать прямой угол.','Пусть P — прямые плоскости. ∃a,b∈P: a⊥b.'),('Квадрат правильной дроби всегда меньше самой дроби.','Пусть P — положительные правильные дроби. ∀p∈P: p²<p.'),('Куб натурального числа может быть равен самому числу.','∃n∈N: n³=n.')]
add(121,'Запиши утверждения с помощью кванторов.',[W(f'{i})',p,a,'Сначала укажи множество значений переменной, затем выбери квантор по словам «каждый» или «существует».') for i,(p,a) in enumerate(rows121,1)])
add(122,'Придумай и запиши собственные высказывания с кванторами.',[
W('1)','Высказывание о существовании.','Например: ∃n∈N: n²=16.','Свидетель n=4.', ['Есть квантор ∃ и область переменной.','Смысл записи соответствует русской формулировке.']),
W('2)','Общее высказывание.','Например: ∀n∈N: n+1>n.','Следующее натуральное число больше предыдущего.', ['Есть квантор ∀ и область переменной.','Свойство сформулировано для каждого элемента области.'])])
add(123,'С помощью ∃ и ∀ преврати предложения в истинные высказывания. Укажи другой способ.',[
W('1)','n(n+1) — простое число.','∃n∈N: n(n+1) — простое.','При n=1 получается 2. Квантор ∀ не подходит: при n=2 получается 6.'),
W('2)','n/(n+4) — правильная дробь.','∀n∈N: n/(n+4) — правильная дробь.','0<n<n+4. Высказывание с ∃ также истинно, но утверждение со ∀ сильнее.'),
W('3)','6k — составное число.','∀k∈N: 6k — составное число.','6k=2·3k, оба множителя больше 1.'),
W('4)','2p/(q+1) — сократимая дробь.','∃p,q∈N: 2p/(q+1) сократима.','Например, p=1,q=3: 2/4. Общее утверждение ложно: p=1,q=2 даёт 2/3.'),
W('другой-способ','Как ещё получить высказывание?','Подставить конкретные допустимые значения всех переменных.','Например, в пункте 1 поставить n=1.')])
rules124=[('Переместительное и сочетательное свойства сложения.','∀a,b∈R: a+b=b+a; ∀a,b,c∈R: (a+b)+c=a+(b+c).'),('Переместительное и сочетательное свойства умножения.','∀a,b∈R: ab=ba; ∀a,b,c∈R: (ab)c=a(bc).'),('Распределительное свойство умножения.','∀a,b,c∈R: (a+b)c=ac+bc.'),('Вычитание числа из суммы.','∀a,b,c∈R при допустимых вычитаниях: (a+b)−c=(a−c)+b=a+(b−c).'),('Вычитание суммы из числа.','∀a,b,c∈R при допустимых вычитаниях: a−(b+c)=a−b−c.'),('Деление числа на произведение.','∀a,b,c∈R при b≠0,c≠0: a:(bc)=(a:b):c=(a:c):b.'),('Деление произведения на число.','∀a,b,c∈R при c≠0: ab:c=(a:c)b=a(b:c).'),('Деление суммы и разности на число.','∀a,b,c∈R при c≠0 и допустимых вычитаниях: (a+b):c=a:c+b:c; (a−b):c=a:c−b:c.')]
add(124,'Запиши правила с квантором общности. R — рассматриваемое множество дробных чисел; во всех формулах действия должны быть определены.',[W(f'{i})',p,a,'Укажи область чисел; при работе только с неотрицательными дробями разрешены лишь те вычитания, которые не выводят из этой области. Нулевой делитель исключается.') for i,(p,a) in enumerate(rules124,1)])
proof125=[('∃n∈N: n²>30.','Например, n=6: 36>30.'),('∃a,b∈N: a=b².','Например, a=4,b=2: 4=2².'),('∃x,y,z∈N: x²+y²=z².','x=3,y=4,z=5: 9+16=25.'),('∃x,y,z∈N: x/y=y/z.','x=1,y=2,z=4: 1/2=2/4.'),('∀n∈N: n+(n+1) нечётно.','n+(n+1)=2n+1 — нечётное число.'),('∀n∈N: n(n+1) чётно.','Из двух соседних натуральных чисел одно чётно; произведение имеет множитель 2.'),('∀n∈N: n(n+1)(n+2) кратно 6.','Среди трёх последовательных натуральных чисел есть кратное 3 и есть чётное. Произведение кратно взаимно простым 2 и 3, значит кратно 6.'),('∀m,n∈N: (m/n)²=m²/n².','(m/n)²=(m/n)·(m/n)=(m·m)/(n·n)=m²/n²; n≠0.')]
add(125,'Прочитай утверждения и докажи их истинность.',[W(f'{i})',p,a,a,[('Дан конкретный пример, удовлетворяющий всем условиям.' if i<=4 else 'Доказательство относится к произвольному натуральному числу, а не только к примеру.'),a]) for i,(p,a) in enumerate(proof125,1)])
proof126=[('∀a∈R: a²>a.','∃a∈R: a²≤a.','Контрпример a=1/2: 1/4<1/2.'),('∀b∈N: b²+b+1 — простое.','∃b∈N: b²+b+1 не простое.','b=4 даёт 21=3·7.'),('∀x,y∈N: (x+y)²=x²+y².','∃x,y∈N: (x+y)²≠x²+y².','x=y=1: 4≠2.'),('∀m,n∈N: m/n=n/m.','∃m,n∈N: m/n≠n/m.','m=1,n=2: 1/2≠2.'),('∃a,b∈N: (a+b)²=5.','∀a,b∈N: (a+b)²≠5.','a+b — натуральное; между квадратами 2²=4 и 3²=9 нет других квадратов натуральных чисел.'),('∃c,d∈N: c²+d²=6.','∀c,d∈N: c²+d²≠6.','Если хотя бы одно ≥3, сумма ≥10. Иначе квадраты 1 или 4, суммы 2,5,8 — не 6.'),('∃x,y∈N: x+y=7 и xy=7.','∀x,y∈N: x+y≠7 или xy≠7.','Из xy=7 следует пара 1 и 7; её сумма 8. При отрицании «и» получаем «или».'),('∃m,n,k∈N: m/n≠mk/(nk).','∀m,n,k∈N: m/n=mk/(nk).','Основное свойство дроби: умножение числителя и знаменателя на одно и то же ненулевое k не меняет значение.')]
add(126,'Опровергни утверждения и построй отрицания. R — множество дробей.',[W(f'{i})',p,'Ложно. Отрицание: '+neg,why) for i,(p,neg,why) in enumerate(proof126,1)])
rows127=[('Р','19 999 кратно 9.','Ложно: сумма цифр 37.'),('А','1275 делится на 3 и на 5.','Истинно: сумма цифр 15, последняя цифра 5.'),('С','1275 кратно 15.','Истинно: делится на взаимно простые 3 и 5.'),('И','6 — делитель 360 106.','Ложно: сумма цифр 16, нет делимости на 3.'),('Н','12 345 678 делится на 18.','Истинно: чётное, сумма цифр 36 кратна 9.'),('Т','1400+56 кратно 5.','Ложно: 1456 оканчивается на 6.'),('Я','3737−36 не делится на 37.','Истинно: 3701=37·100+1.'),('В','9·36·151 нечётно.','Ложно: множитель 36 чётный.'),('Б','11·25·508 кратно 10.','Истинно: 25·508=12700.'),('Е','452·49+702 делится на 7.','Ложно: первое слагаемое кратно 7, а 702=7·100+2.')]
add(127,'Из букв истинных высказываний составь слово и объясни значение.',[W(l,p,a,a) for l,p,a in rows127]+[W('слово','Собери А,С,Н,Я,Б.','БАСНЯ.','Короткое поучительное произведение, часто с аллегорическими персонажами и моралью.')])
tests128={1:['3.2+7.5','9.2-2','8-1.7','2.8+0.7','0.06+2.9','12.5-0.05','2.78-1.28','5.6+3.4','3.14-1.9','4.5+0.63'],2:['3.7/0.01','2.4*10','5.8*0.1','9.2/100','0.4*0.7','1.8/0.02','30*0.05','6/20','5.4/0.054','0.09*0.09'],3:['530-52.9','12.92+7.315','117.171+7.129','4.07-1.976'],4:['9.78*30.6','0.805*70600','19.212/2.4','0.0228/0.075']}
add(128,'Счёт-тест: вычисли исходные примеры. В тестах 1 и 2 в учебнике записываются только ответы.',[E(f'{t}-{i}',s,s.replace('.',',').replace('*','·').replace('/',':')) for t,arr in tests128.items() for i,s in enumerate(arr,1)])
add(129,'Подставь цифры в 7*2*, чтобы число делилось на заданное. Укажи все решения.',[W(l+')',f'Делимость на {d}.','; '.join(str(7000+100*a+20+b) for a in range(10) for b in range(10) if (7000+100*a+20+b)%d==0)+'.',why) for l,d,why in [('а',18,'Нужны чётная последняя цифра и сумма цифр, кратная 9.'),('б',30,'Последняя цифра 0, сумма цифр кратна 3.'),('в',45,'Последняя цифра 0 или 5, сумма цифр кратна 9.'),('г',36,'Последние две цифры кратны 4, сумма цифр кратна 9.')]])
add(130,'Построй математические модели задач.',[
W('1)','В хоре 148 детей. В младшей группе вдвое больше, чем в средней, и на 32 больше, чем в старшей. Сколько в каждой?','Если в средней x, то x+2x+(2x−32)=148. Средняя 36, младшая 72, старшая 40.','5x−32=148, 5x=180, x=36.', ['Три группы выражены через одну переменную.','Их сумма равна 148.','Разница младшей и старшей — 32.'],[S('Найди 5x.','180','148+32=180.'),S('Найди среднюю группу.','36','180:5=36.'),S('Найди младшую.','72','2·36=72.'),S('Найди старшую.','40','72−32=40.')]),
W('2)','Мотоциклист: при увеличении скорости на 4 км/ч путь занимает 4,5 ч, при уменьшении на 6 км/ч — 6 ч. Найди скорость.','4,5(v+4)=6(v−6), v>6. Скорость 36 км/ч.','Оба произведения равны одному расстоянию; 4,5v+18=6v−36.', ['Приравнены расстояния, не времена.','Выражения скоростей v+4 и v−6.','Ответ 36 км/ч.'],[S('Найди разность постоянных частей 18+36.','54','1,5v=54.'),S('Найди v.','36','54:1,5=36.'),S('Проверь расстояние.','180','(36+4)·4,5=(36−6)·6=180 км.')]),
W('3)','Оператор набирал 240 страниц на 3 страницы/ч быстрее плана и закончил на 4 ч раньше. Сколько времени работал?','При фактическом времени t: 240/t−240/(t+4)=3. Решение t=16 ч.','Эквивалентно t(t+4)=320; 16·20=320. Фактическая скорость 15 стр./ч, плановая 12 стр./ч.', ['Запланированное время t+4.','Разность скоростей равна 3, обе работы по 240 страниц.','16 ч проверено подстановкой.']) ,
W('4)','240 пассажиров разместили в 108 каютах на 1,2,3 места. Одноместных вдвое меньше трёхместных. Сколько кают каждого вида?','Если одноместных x, трёхместных 2x, двухместных 108−3x: x+2(108−3x)+6x=240. Ответ: 24;36;48 кают.','216+x=240, x=24; двухместных 108−72=36.', ['Число кают суммируется до 108.','Число мест суммируется до 240.','Трёхместных вдвое больше одноместных.'])])
add(131,'Упрости уравнения, используя свойства действий, затем реши. Сравни строки и столбцы.',[
N('1)','x+2x+3x+4x=48.','4.8',[S('Сложи коэффициенты.','10','1+2+3+4=10.'),S('Реши 10x=48.','4.8','48:10=4,8.')]),
N('2)','3,2y−1,4y+y−0,6y=5,5.','2.5',[S('Собери коэффициенты.','2.2','3,2−1,4+1−0,6=2,2.'),S('Реши 2,2y=5,5.','2.5','5,5:2,2=2,5.')]),
N('3)','1 3/5 z+z−4/15 z+7/6 z=2 1/3.','2/3',[S('Сложи коэффициенты при z.','7/2','8/5+1−4/15+7/6=7/2.'),S('Найди z.','2/3','(7/3):(7/2)=2/3.')]),
N('4)','2x+5+x+14+6x=64.','5',[S('Собери коэффициенты при x.','9','2+1+6=9.'),S('Найди правую часть после вычитания постоянных.','45','64−5−14=45.'),S('Найди x.','5','45:9=5.')]),
N('5)','1,8+3,5y+0,9+y=16,2.','3',[S('Сложи коэффициенты.','4.5','3,5+1=4,5.'),S('Вычти постоянные слагаемые из 16,2.','13.5','16,2−1,8−0,9=13,5.'),S('Найди y.','3','13,5:4,5=3.')]),
N('6)','4 1/2 z+7/9 z+2 1/3+1/6 z=5 1/18.','1/2',[S('Сложи коэффициенты при z.','49/9','9/2+7/9+1/6=49/9.'),S('Вычти постоянное 2 1/3 из правой части.','49/18','91/18−7/3=49/18.'),S('Найди z.','1/2','(49/18):(49/9)=1/2.')]),
W('сравнение','Что общего по строкам и столбцам?','В каждой строке одинаковый вид коэффициентов: натуральные, десятичные, обыкновенные дроби. В левом столбце только слагаемые с переменной; в правом есть также постоянные слагаемые.','Во всех случаях используем распределительное свойство для приведения подобных слагаемых.')])
rows132=[('1)','(8.46+2.008)+(17.992+1.54)','(8,46+2,008)+(17,992+1,54)','Сгруппируй 8,46+1,54=10 и 2,008+17,992=20; сумма 30. Переместительное и сочетательное свойства.'),('3)','2.5*7.89*0.04*100','2,5·7,89·0,04·100','2,5·0,04·100=10, значит результат 78,9. Перестановка и группировка множителей.'),('4)','(7/18)*(20*16.2)*((18/7)*0.5)','7/18·(20·16,2)·(18/7·0,5)','7/18·18/7=1, 20·0,5=10, ответ 162.'),('5)','(1/8+m(1,1,16)-13/24+1/3)*48','(1/8+1 1/16−13/24+1/3)·48','Распределим 48 по слагаемым: 6+51−26+16=47.'),('6)','(9.09+999.9+900.09)/9','(9,09+999,9+900,09):9','Разделим слагаемые на 9: 1,01+111,1+100,01=212,12.'),('7)','(1.5*4.28*0.04)/4.28','(1,5·4,28·0,04):4,28','Сократим одинаковые ненулевые множитель и делитель: 1,5·0,04=0,06.'),('8)','(2*2*3*3*5*7*11)/(2*3*3*11)','(2·2·3·3·5·7·11):(2·3·3·11)','После сокращения остаётся 2·5·7=70.'),('9)','(m(1,3,11)+m(5,2,79)+m(7,8,11))-m(4,2,79)','(1 3/11+5 2/79+7 8/11)−4 2/79','1 3/11+7 8/11=9; 5 2/79−4 2/79=1; всего 10.'),('10)','m(7,3,25)-(m(4,3,25)+m(1,5,18))','7 3/25−(4 3/25+1 5/18)','Сначала 7 3/25−4 3/25=3, потом 3−1 5/18=1 13/18.')]
