def digit_values(n):return list(map(int,str(n)))
def number_list(numbers):return '; '.join(map(str,numbers))+'.'

solutions149=[([n for n in range(10,100) if sum(digit_values(n))==12 and math.prod(digit_values(n))==35],'Сумма цифр двузначного числа 12, произведение 35.','Цифры 5 и 7; учитывай оба порядка.'),([n for n in range(10,100) if sum(digit_values(n))==11 and math.prod(digit_values(n))==24],'Сумма цифр двузначного числа 11, произведение 24.','Цифры 3 и 8.'),([n for n in range(100,1000) if sum(digit_values(n))==6 and math.prod(digit_values(n))==6],'Сумма и произведение цифр трёхзначного числа равны 6.','Цифры 1,2,3 во всех шести порядках.'),([n for n in range(1000,10000) if sum(digit_values(n))==2 and math.prod(digit_values(n))==0],'Сумма цифр четырёхзначного числа 2, произведение 0.','Либо первая цифра 2, остальные 0, либо первая 1 и ещё одна 1 в одной из трёх позиций.')]
