add(175,'Велосипедист проехал путь A–B за 5 ч, мотоциклист за 2 ч. Скорость мотоциклиста на 23,4 км/ч больше. Переведи условие на математический язык и найди расстояние.',[W('1','Выбери неизвестную скорость или расстояние.','Если скорость велосипедиста v, то 5v=2(v+23,4). Эквивалентно для расстояния S: S/2−S/5=23,4. Ответ: 78 км.','Из 5v=2v+46,8 получаем 3v=46,8, v=15,6. Тогда S=5·15,6=78 км.', ['Приравнены расстояния двух участников.','Разность скоростей 23,4 км/ч.','Получено расстояние 78 км.'],[S('Найди 3v.','46.8','2·23,4=46,8.'),S('Найди скорость велосипедиста.','15.6','46,8:3=15,6 км/ч.'),S('Найди расстояние.','78','15,6·5=78 км.'),S('Проверь скорость мотоциклиста.','39','15,6+23,4=39 км/ч;39·2=78 км.')])])

def build():
    numbers=[e['number'] for e in BOOK]
    assert len(numbers)==len(set(numbers))
    assert set(numbers)==set(range(1,176)), 'The final range must contain every source exercise 1–175.'
    all_ids=set()
    for exercise in BOOK:
        for part in exercise['parts']:
            assert re.fullmatch(r'[0-9]{3}-[a-z0-9-]+',part['id']),part['id']
            assert part['id'] not in all_ids,part['id']
            all_ids.add(part['id'])
            assert part['prompt'] and part['steps'] and part['answer']
            if part['kind']=='expression':
                value=ev(part['expression'])
                if 'rounding' in part:value=rounded(value,part['rounding']['places'])
                assert rat(part['answer'])==value,(part['id'],'answer')
            if part['kind']=='choice':assert part['answer'] in part['choices']
            if part['kind']=='written':assert part['criteria']
            if part['kind']=='numeric':assert rat(part['steps'][-1]['answer'])==rat(part['answer']),part['id']
            assert all(step.get('prompt') and step.get('explanation') for step in part['steps']),part['id']
    # Independent fixed-value checks: published answers on PDF p111 and direct
    # hand calculations of source expressions whose parentheses OCR loses.
    expected={
        (13,'а)'):'10',(13,'б)'):'9.1',(23,'а)'):'0.02',(23,'б)'):'46.47',(24,'1'):'3.6',
        (52,'а-1'):'510',(52,'а-2'):'300',(52,'б-1'):'100.70',(52,'б-2'):'3.00',
        (56,'1)'):'53',(56,'2)'):'5',(65,'1-точно'):'17/12',(65,'2-точно'):'2/21',
        (65,'1-десятых'):'1.4',(65,'1-сотых'):'1.42',(65,'1-тысячных'):'1.417',
        (65,'2-десятых'):'0.1',(65,'2-сотых'):'0.10',(65,'2-тысячных'):'0.095',
        (68,'1)'):'0.5',(68,'2)'):'16',(72,'4)'):'0',(91,'5)'):'1',(91,'6)'):'0.28',
        (94,'1)'):'3.2',(94,'2)'):'5.76',(95,'1)'):'0.53',(95,'2)'):'0.55',(97,'1'):'85',
        (101,'5)'):'0.35',(101,'6)'):'1/9',(101,'7)'):'310.2',(101,'8)'):'234.32',
        (106,'3-4'):'0.048',(112,'1)'):'0.5',(112,'2)'):'15/7',
        (114,'1-5'):'16.16',(114,'2-1'):'8/9',(114,'2-2'):'17/10',(114,'2-3'):'28/11',(114,'2-4'):'41/12',
        (119,'1'):'2',(131,'3)'):'2/3',(131,'4)'):'5',(131,'5)'):'3',(131,'6)'):'0.5',
        (132,'4)'):'162',(132,'5)'):'47',(132,'10)'):'31/18',(137,'1)'):'0.09',(137,'2)'):'1',
        (139,'1)'):'55',(139,'2)'):'7',(151,'5)'):'2.5',(151,'6)'):'12/7',(151,'7)'):'1.4',(151,'8)'):'10',
        (152,'1)'):'36',(152,'2)'):'40',(155,'а)'):'1015',(155,'б)'):'290',
        (156,'1'):'0',(159,'1)'):'11',(159,'2)'):'35',(163,'1'):'1',
        (164,'1)'):'24.05',(164,'2)'):'68.972',(164,'3)'):'220.024',(164,'4)'):'7.008',(164,'5)'):'45.5758',
        (165,'1'):'36',(170,'1)'):'10/3',(170,'2)'):'1816.3',(172,'1'):'0.48',
        (173,'1)'):'0.4',(173,'2)'):'2',(173,'3)'):'0.2',(173,'4)'):'4.5'
    }
    lookup={(e['number'],p['label']):p for e in BOOK for p in e['parts']}
    for key,value in expected.items():assert rat(lookup[key]['answer'])==rat(value),(key,lookup[key]['answer'],value)
